      ar: 'دليل شامل ومفصل لنقل ضيوف الرحمن من مكة إلى المدينة المنورة: مقارنة متوازنة مع قطار الحرمين، اختيار السيارة المناسبة للأمتعة، وقت الرحلة، والأسعار الثابتة مع الدفع للسائق فقط.',
      en: 'Comprehensive guide to private chauffeur transfers from Makkah to Madinah: balanced train comparison, vehicle selection for family luggage, driving duration, and fixed rates with Pay the Driver Only.',
      ms: 'Panduan lengkap pemindahan peribadi dari Makkah ke Madinah: perbandingan adil dengan kereta api, pilihan kenderaan, masa perjalanan, dan kadar tetap dengan Bayar kepada Pemandu Sahaja.',
      id: 'Panduan lengkap transportasi privat Makkah ke Madinah: komparasi berimbang dengan kereta cepat, pemilihan mobil koper keluarga, durasi perjalanan, dan tarif pasti bayar langsung ke sopir.',
