          fr: 'Vous pouvez réserver facilement en ligne sur notre site ou directement via WhatsApp en renseignant votre itinéraire, date et heure de prise en charge, ainsi que le nombre de passagers et de bagages. Confirmation immédiate sans aucun acompte : paiement direct au chauffeur à l’arrivée sécurisée.',
          es: 'Puede reservar fácilmente en nuestra web o directamente por WhatsApp indicando ruta, fecha y hora de recogida, pasajeros y maletas. La confirmación es inmediata y sin anticipos: abona el importe directamente al chófer al llegar a salvo a su destino.',
