          de: 'Ja, absolut. Dies ist unsere am häufigsten gebuchte Strecke. Ihr Flug wird live verfolgt und Ihr Chauffeur empfängt Sie mit einem Namensschild direkt im Terminal, hilft beim Gepäck und fährt Sie auf direktem Weg zu Ihrem Hotel in Mekka.',
