          ur: 'جدہ ایئرپورٹ پر معتمرین کا استقبال کیسے کیا جاتا ہے؟',
          fr: 'Comment se déroule l’accueil du pèlerin de l’Omra à l’aéroport de Djeddah ?',
          es: '¿Cómo se recibe al peregrino de la Umrah en el aeropuerto de Yeda?',
          de: 'Wie läuft der Empfang von Umrah-Pilgern am Flughafen Dschidda ab?',
          hi: 'जेद्दा हवाई अड्डे पर उमरा यात्रियों का स्वागत कैसे किया जाता है?',
          tr: 'Cidde Havalimanı’nda umre yolcuları nasıl karşılanır?',
