        answer: {
          ar: 'يقوم منسق العمليات بتزويدك ببيانات السائق ورقم لوحة السيارة قبل وصولك بساعتين عبر الواتساب. وفور هبوط الطائرة وخروجك من صالة الوصول، يتواصل معك السائق ليقابلك عند نقطة الالتقاء المتفق عليها، ويساعدك في نقل الأمتعة إلى صندوق السيارة والانطلاق المباشر إلى فندقك في مكة المكرمة.',
          en: 'Our operations dispatcher sends you your chauffeur’s name, WhatsApp contact, and vehicle plate number 2 to 3 hours before landing. Once you clear baggage claim and enter the arrivals concourse, your chauffeur coordinates with you, meets you at the agreed pickup area, loads your luggage, and drives you directly to your Makkah hotel.',
          ms: 'Penyelaras operasi kami menghantar nama pemandu, nombor WhatsApp, dan nombor plat kenderaan kira-kira 2 hingga 3 jam sebelum mendarat. Sebaik sahaja anda keluar dari balai ketibaan, pemandu akan berhubung dan menyambut anda di kawasan pertemuan yang dipersetujui, membantu mengangkat bagasi, dan memandu terus ke hotel anda di Makkah.',
          id: 'Koordinator operasional kami mengirimkan nama sopir, nomor WhatsApp, dan nomor pelat mobil 2 hingga 3 jam sebelum mendarat. Setelah Anda mengambil koper dan keluar ke aula kedatangan, sopir menyambut Anda di titik temu yang disepakati, membantu mengangkat koper, dan mengantar langsung ke hotel Anda di Makkah.',
          ur: 'ہمارے آپریشنز مینیجر پرواز اترنے سے 2 تا 3 گھنٹے قبل واٹس ایپ پر ڈرائیور کا نام، رابطہ نمبر اور گاڑی کا نمبر بھیج دیتے ہیں۔ جونہی آپ لاؤنج سے باہر نکلتے ہیں، ڈرائیور مقررہ مقام پر آپ کا استقبال کرتا ہے، سامان گاڑی میں رکھواتا ہے اور مکہ کے ہوٹل کے لیے روانہ ہوتا ہے۔',
          fr: 'Notre coordinateur vous transmet le nom du chauffeur, son contact WhatsApp et le numéro de plaque 2 à 3 heures avant l’atterrissage. Dès votre sortie avec vos bagages, votre chauffeur vous accueille au point convenu, charge vos valises et vous conduit directement à votre hôtel à La Mecque.',
          es: 'Nuestro coordinador le envía el nombre del chófer, su contacto de WhatsApp y la matrícula del coche unas 2 o 3 horas antes de aterrizar. Al salir de la terminal con su equipaje, el chófer le recibe en el punto acordado, carga las maletas y le traslada directamente a su hotel en La Meca.',
          de: 'Unsere Disposition sendet Ihnen 2 bis 3 Stunden vor der Landung den Namen des Chauffeurs, seine WhatsApp-Nummer und das Kennzeichen. Nach der Gepäckausgabe empfängt Sie Ihr Chauffeur am Treffpunkt, verlädt die Koffer und fährt Sie direkt zu Ihrem Hotel in Mekka.',
          hi: 'हमारे ऑपरेशंस मैनेजर लैंडिंग से 2-3 घंटे पहले व्हाट्सएप पर ड्राइवर का नाम, नंबर और गाड़ी की प्लेट भेजते हैं। जैसे ही आप आगमन हॉल से बाहर आते हैं, ड्राइवर तय स्थान पर आपका स्वागत करता है, सामान रखने में मदद करता है और सीधे मक्का के होटल ले जाता है।',
          tr: 'Operasyon sorumlumuz inişten 2-3 saat önce şoför adı, WhatsApp numarası ve plaka bilgisini iletir. Bagajınızı alıp çıkış yaptığınızda şoförünüz sizi belirlenen noktada karşılar, valizlerinizi yerleştirir ve doğrudan Mekke’deki otelinize ulaştırır.',
        },
