          en: 'For families of 4 to 6 passengers carrying 4 to 6 large check-in suitcases, a GMC Yukon XL or Hyundai Staria VIP is the premier choice. For larger family groups of 6 to 10 passengers with 8 to 10 large suitcases, the high-roof Toyota HiAce GL provides unmatched passenger comfort and cargo room.',
          ms: 'Bagi keluarga seramai 4 hingga 6 orang bersama 4 hingga 6 beg besar, GMC Yukon XL atau Hyundai Staria VIP adalah pilihan yang sangat ideal. Manakala bagi kumpulan keluarga seramai 6 hingga 10 orang dengan 8 hingga 10 beg besar, van Toyota HiAce bumbung tinggi adalah pilihan terbaik.',
          id: 'Untuk keluarga 4 hingga 6 orang dengan 4 hingga 6 koper besar, armada GMC Yukon XL atau Hyundai Staria VIP adalah pilihan paling sempurna. Sedangkan untuk keluarga besar 6 hingga 10 penumpang dengan 8 hingga 10 koper besar, Toyota HiAce atap tinggi sangat direkomendasikan.',
          ur: '4 سے 6 افراد پر مشتمل فیملی اور 4 سے 6 بڑے سوٹ کیسز کے لیے GMC یوکون XL یا ہنڈائی اسٹاریا VIP بہترین انتخاب ہے۔ اگر فیملی میں 6 سے 10 افراد ہوں اور 8 سے 10 بڑے بیگز ہوں تو اونچی چھت والی ٹویوٹا ہائی ایس سب سے موزوں رہتی ہے۔',
          fr: 'Pour les familles de 4 à 6 personnes avec 4 à 6 grandes valises, le GMC Yukon XL ou le Hyundai Staria VIP constitue le choix idéal. Pour les groupes de 6 à 10 personnes avec 8 à 10 grandes valises, le Toyota HiAce à toit surélevé offre un confort et un coffre imbattables.',
          es: 'Para familias de 4 a 6 personas con 4 a 6 maletas grandes, el GMC Yukon XL o el Hyundai Staria VIP son la elección ideal. Para grupos familiares de 6 a 10 personas con 8 a 10 maletas grandes, la furgoneta Toyota HiAce de techo alto ofrece un espacio insuperable.',
          de: 'Für Familien mit 4 bis 6 Personen und 4 bis 6 großen Koffern ist ein GMC Yukon XL oder Hyundai Staria VIP die perfekte Wahl. Bei 6 bis 10 Personen mit 8 bis 10 großen Koffern bietet der Toyota HiAce mit Hochdach optimalen Komfort und enormen Stauraum.',
          hi: '4 से 6 सदस्यों वाले परिवार और 4 से 6 बड़े सूटकेस के लिए GMC यूकॉन XL या हुंडई स्टारिया VIP सबसे आदर्श है। 6 से 10 सदस्यों और 8 से 10 बड़े सूटकेस वाले बड़े परिवारों के लिए ऊंची छत वाली टोयोटा हायेस सबसे बेहतरीन विकल्प है।',
          tr: '4 ila 6 kişilik ve 4 ila 6 büyük valizli aileler için GMC Yukon XL veya Hyundai Staria VIP mükemmel bir tercihtir. 6 ila 10 kişilik daha kalabalık ve 8 ila 10 valizli aile grupları için ise yüksek tavanlı Toyota HiAce geniş bagaj hacmiyle en uygun seçenektir.',
