          en: 'No, absolutely not. At Duyuf Alrahman VIP, we strictly adhere to a zero-prepayment policy for the peace of mind of our pilgrim guests. Your booking is officially confirmed on WhatsApp without a credit card or deposit, and you pay your driver directly upon safe arrival at your Makkah hotel.',
