          en: 'You can check the availability of hourly packages (4-hour or 8-hour blocks) directly in our online booking engine, or by messaging our reservations team on WhatsApp with your desired city (Makkah or Jeddah), travel date, and preferred vehicle category for instant confirmation and official rates.',
          ms: 'Anda boleh menyemak ketersediaan pakej jam (blok 4 jam atau 8 jam) melalui enjin tempahan laman web kami, atau menghantar mesej WhatsApp kepada pasukan kami dengan menyatakan bandar (Makkah atau Jeddah), tarikh, dan jenis kenderaan untuk pengesahan segera.',
          id: 'Anda dapat memeriksa ketersediaan paket sewa per jam (blok 4 jam atau 8 jam) melalui mesin pemesanan di situs kami, atau mengirim pesan WhatsApp dengan menyebutkan kota tujuan (Makkah atau Jeddah), tanggal sewa, dan jenis armada untuk konfirmasi instan.',
          ur: 'آپ ہماری ویب سائٹ کے بکنگ انجن پر 4 یا 8 گھنٹے کے پیکیجز کی دستیابی چیک کر سکتے ہیں، یا واٹس ایپ پر اپنی مطلوبہ تاریخ، شہر (مکہ یا جدہ) اور گاڑی کی قسم بتا کر ہماری ٹیم سے فوری دستیابی اور فکس ریٹ کی تصدیق حاصل کر سکتے ہیں۔',
          fr: 'Vous pouvez vérifier la disponibilité des forfaits horaires (blocs de 4 ou 8 heures) directement sur le moteur de réservation de notre site ou en contactant notre équipe sur WhatsApp avec la ville (La Mecque ou Djeddah), la date et le véhicule souhaité.',
