          tr: 'Saatlik paketlerin (4 veya 8 saatlik bloklar) müsaitliğini web sitemizdeki rezervasyon panelinden kontrol edebilir veya WhatsApp üzerinden şehir (Mekke veya Cidde), tarih ve araç tercihinizi belirterek operasyon ekibimizden anında teyit alabilirsiniz.',
