          ar: 'يُفضل حجز سيارة العمرة قبل موعد السفر بـ 24 إلى 48 ساعة على الأقل لضمان تأكيد نوع المركبة المناسبة. وفي مواسم الذروة مثل رمضان وموسم الحج ورجب وشعبان، يُنصح بالحجز المسبق قبل 5 إلى 7 أيام لضمان توفر الفئات العائلية الكبيرة وسيارات VIP الفاخرة.',
          en: 'It is recommended to book your Umrah transportation at least 24 to 48 hours before travel to guarantee vehicle category availability. During peak seasons like Ramadan, Hajj, and school vacations, booking 5 to 7 days in advance ensures access to family SUVs and VIP minivans.',
          ms: 'Sebaiknya buat tempahan sekurang-kurangnya 24 hingga 48 jam lebih awal untuk memastikan kategori kenderaan yang anda inginkan tersedia. Pada musim puncak seperti Ramadan dan cuti sekolah, tempahan 5 hingga 7 hari lebih awal disyorkan.',
          id: 'Disarankan memesan transportasi umrah minimal 24 hingga 48 jam sebelum keberangkatan untuk menjamin ketersediaan kendaraan. Pada musim ramai seperti Ramadhan atau liburan, disarankan memesan 5 hingga 7 hari sebelumnya.',
          ur: 'گاڑی کی دستیابی یقینی بنانے کے لیے سفر سے کم از کم 24 تا 48 گھنٹے قبل بکنگ کروانا بہترین ہے۔ رمضان المبارک اور دیگر رش کے ایام میں 5 تا 7 دن قبل بکنگ کروانا مناسب ہے تاکہ بڑی فیملی گاڑیاں اور وی آئی پی ماڈلز دستیاب رہیں۔',
          fr: 'Il est conseillé de réserver au moins 24 à 48 heures à l’avance pour garantir la catégorie de véhicule souhaitée. Durant les périodes de forte affluence comme le Ramadan, une réservation 5 à 7 jours à l’avance est fortement recommandée.',
          es: 'Se aconseja reservar al menos 24 a 48 horas antes de viajar para asegurar la categoría deseada. En temporadas de alta demanda como Ramadán, se recomienda reservar con 5 a 7 días de antelación para asegurar vehículos familiares grandes.',
          de: 'Es empfiehlt sich, mindestens 24 bis 48 Stunden vor Reiseantritt zu buchen. In Hauptreisezeiten wie dem Ramadan sollten Sie 5 bis 7 Tage im Voraus reservieren, um Großraumfahrzeuge und VIP-Vans zu sichern.',
          hi: 'अपनी पसंद की गाड़ी सुनिश्चित करने के लिए यात्रा से कम से कम 24 से 48 घंटे पहले बुकिंग करने की सलाह दी जाती है। रमज़ान और व्यस्त सीज़न में बड़ी फैमिली गाड़ियों के लिए 5 से 7 दिन पहले बुकिंग करना बेहतर है।',
          tr: 'İstediğiniz araç kategorisini garantiye almak için seyahatten en az 24 ila 48 saat önce rezervasyon yapmanız önerilir. Ramazan ve yoğun tatil dönemlerinde ise büyük aile araçları için 5 ila 7 gün önceden rezervasyon tavsiye edilir.',
