          en: 'A standard private tour takes approximately 3 to 3.5 hours. This is the optimal timeframe covering smooth transit between landmarks with generous time for Sunnah prayers at Masjid Quba, walking around the Uhud battlefield, and visiting Masjid al-Qiblatayn without rushing.',
          ms: 'Lawatan persendirian standard mengambil masa kira-kira 3 hingga 3.5 jam. Tempoh ini sangat sesuai untuk perjalanan lancar, solat sunat di Masjid Quba, melawat Medan Uhud, dan Masjid al-Qiblatayn dengan tenang.',
          id: 'Tur privat standar berlangsung sekitar 3 hingga 3,5 jam. Durasi ini sangat ideal untuk mencakup perjalanan santai antar lokasi, salat sunnah di Masjid Quba, ziarah ke Uhud, dan Masjid Qiblatain tanpa terburu-buru.',
          ur: 'معیاری پرائیویٹ ٹور عام طور پر 3 سے 3.5 گھنٹے کا ہوتا ہے۔ اس دوران مسجد قباء میں نفل نماز، جبل رماۃ اور شہدائے احد کی زیارت، اور مسجد قبلتین و سبع مساجد کا پرسکون وزٹ باآسانی مکمل ہو جاتا ہے۔',
          fr: 'Une visite privée standard dure environ 3 à 3,5 heures. Cette durée est idéale pour relier paisiblement les étapes, accomplir les prières à la mosquée Quba, explorer le champ de bataille d’Uhud et la mosquée des Deux Qiblas sans précipitation.',
          es: 'Un tour privado estándar dura entre 3 y 3,5 horas. Este tiempo es ideal para recorrer con calma los lugares santos, rezar en la Mezquita de Quba, visitar el Monte Uhud y la Mezquita de las dos Qiblas sin prisas.',
          de: 'Eine private Standardtour dauert etwa 3 bis 3,5 Stunden. Dies ist der ideale Zeitrahmen, um entspannt zwischen den Stätten zu reisen, in der Masjid Quba zu beten und das Uhud-Schlachtfeld sowie die Qiblatayn-Moschee zu besichtigen.',
          hi: 'मानक निजी टूर में लगभग 3 से 3.5 घंटे का समय लगता है। यह समय बिना किसी जल्दबाजी के मस्जिद कुबा में नमाज़, उहुद पहाड़ की ज़ियारत और मस्जिद क़िबलतैन के दर्शन के लिए पर्याप्त है।',
          tr: 'Standart özel tur yaklaşık 3 ila 3,5 saat sürer. Bu süre; Kuba Mescidi’nde nafile namaz kılmak, Uhud Şehitliği’ni ziyaret etmek ve Mescid-i Kıbleteyn’i acele etmeden gezmek için en ideal zaman dilimidir.',
