          en: 'What is the payment policy for the Madinah Ziyarat tour?',
          ms: 'Apakah polisi pembayaran bagi lawatan ziarah Madinah?',
          id: 'Bagaimana kebijakan pembayaran untuk tur ziarah Madinah?',
          ur: 'مدینہ زیارات ٹور کی ادائیگی (پیمنٹ) کی پالیسی کیا ہے؟',
          fr: 'Quelle est la politique de paiement pour la visite des Ziyarat de Médine ?',
          es: '¿Cuál es la política de pago para el tour de Ziyarat en Medina?',
          de: 'Welche Zahlungsbedingungen gelten für die Madinah Ziyarat Tour?',
          hi: 'मदीना ज़ियारत टूर के लिए भुगतान (Payment) की क्या नीति है?',
          tr: 'Medine ziyaret turu için ödeme koşulları nelerdir?',
