          tr: '%100 Şoföre Doğrudan Ödeme (Ön Ödemesiz / Zero Prepayment) prensibiyle çalışıyoruz. Önceden online ödeme veya kredi kartı gerekmez; anlaşılan sabit ücreti otelde şoförünüze nakit (Riyal) veya kartla ödersiniz.',
