          en: 'The prime time is early morning (between 7:00 AM and 7:30 AM) after breakfast. Temperatures are pleasantly cool, crowds at Masjid Quba are minimal, and you return comfortably before Dhuhr prayer. Alternatively, late afternoon after Asr prayer is also pleasant.',
          ms: 'Waktu paling sesuai ialah awal pagi (antara 7:00 pagi dan 7:30 pagi) selepas sarapan. Suasana masih sejuk, jemaah di Masjid Quba belum terlalu ramai, dan anda akan pulang sebelum solat Zohor. Petang selepas Asar juga waktu yang baik.',
          id: 'Waktu paling ideal adalah pagi hari (antara pukul 07.00 hingga 07.30) setelah sarapan. Suhu udara masih sejuk, antrean di Masjid Quba relatif lengang, dan Anda kembali ke hotel sebelum azan Zuhur. Waktu sore setelah Asar juga cukup nyaman.',
          ur: 'سب سے بہترین وقت صبح سویرے ناشتے کے بعد (صبح 7:00 سے 7:30 بجے) ہے۔ اس وقت موسم خوشگوار ہوتا ہے، رش کم ہوتا ہے، اور آپ ظہر کی نماز سے قبل باآسانی واپس مسجد نبوی پہنچ جاتے ہیں۔ دوسرا بہترین وقت نماز عصر کے بعد کا ہے۔',
          fr: 'Le créneau idéal est le matin tôt (entre 7h00 et 7h30) après le petit-déjeuner. Les températures sont agréables, l’affluence à la mosquée Quba est faible et vous rentrez avant la prière de Dhuhr. La fin d’après-midi après Asr est une autre excellente option.',
          es: 'El momento idóneo es temprano por la mañana (entre las 7:00 y las 7:30) tras el desayuno. El clima es fresco, hay menos afluencia en Quba y regresará antes de la oración de Dhuhr. La tarde después de Asr también es una buena alternativa.',
          de: 'Die beste Zeit ist der frühe Morgen (zwischen 07:00 und 07:30 Uhr) nach dem Frühstück. Die Temperaturen sind angenehm kühl, die Besucherzahlen an der Quba-Moschee überschaubar und Sie kehren vor dem Dhuhr-Gebet zurück.',
          hi: 'सबसे अच्छा समय सुबह नाश्ते के बाद (सुबह 7:00 से 7:30 बजे) है। इस समय मौसम सुहावना रहता है, मस्जिद कुबा में भीड़ कम होती है और आप ज़ोहर की नमाज़ से पहले आराम से होटल लौट आते हैं। दूसरा विकल्प असर की नमाज़ के बाद का है।',
          tr: 'En ideal zaman kahvaltıdan hemen sonra sabahın erken saatleridir (07:00 - 07:30 arası). Hava serin olur, Kuba Mescidi’ndeki kalabalık azdır ve öğle namazından önce otelinize rahatça dönersiniz. İkindi sonrası da güzel bir tercihtir.',
