          ur: 'جی ہاں، بالکل۔ گاڑی اور پرائیویٹ ڈرائیور پورے ٹور کے دوران صرف آپ کی فیملی کے لیے مخصوص ہوتے ہیں۔ ڈرائیور ہر جگہ مقررہ پارکنگ میں آپ کا انتظار کرتا ہے اور زیارت مکمل ہونے پر گیٹ پر گاڑی حاضر کر دیتا ہے۔',
          fr: 'Oui, absolument. Le chauffeur et le véhicule sont exclusivement dédiés à votre famille pendant toute la durée de la visite. Le chauffeur stationne à proximité à chaque arrêt, attend patiemment et vous récupère à la porte convenue.',
          es: 'Sí, por supuesto. El chofer privado y el vehículo están dedicados exclusivamente a su grupo durante las 3 a 3,5 horas. Aparca en las zonas autorizadas de cada sitio y les recoge en la puerta cuando hayan terminado.',
