          en: 'How do I arrange airport pickup for an elderly relative from Jeddah Airport?',
          ms: 'Bagaimanakah cara mengatur sambutan ketibaan warga emas di Lapangan Terbang Jeddah?',
          id: 'Bagaimana cara mengatur penjemputan bandara untuk lansia di Bandara Jeddah?',
          ur: 'جدہ ایئرپورٹ پر بزرگ کے لیے استقبال کا انتظام کیسے کیا جائے؟',
          fr: 'Comment organiser l’accueil d’un proche âgé à l’aéroport de Djeddah ?',
          es: '¿Cómo organizo la recogida de un familiar mayor en el aeropuerto de Yeda?',
          de: 'Wie organisiere ich die Abholung eines älteren Angehörigen am Flughafen Dschidda?',
          hi: 'जेद्दा एयरपोर्ट पर बुजुर्ग परिजन के पिकअप का सही इंतज़ाम कैसे करें?',
          tr: 'Cidde Havalimanı’nda yaşlı bir yakınım için karşılama transferini nasıl ayarlarım?',
